Import-Module 'c:/Projects/ProphetManX/prophets-pipelines/conventions/scripts/AgentEvidence.psm1' -PassThru | ForEach-Object {
    $ErrorActionPreference = 'Stop'
    $run = 'c:/Projects/ProphetManX/.agent-runs/20260915-2052-logger-overnight-approval'
    $evidence = Join-Path $run 'evidence'
    $protected = Get-Content -LiteralPath (Join-Path $evidence 'on02-protected-specifications-r1.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not (Compare-AgentManifest -Baseline $protected).Matches) { throw 'Protected source/specification drift.' }
    $author = Get-Content -LiteralPath (Join-Path $evidence 'on02-06-step15-test.json') -Raw | ConvertFrom-Json -AsHashtable -Depth 30
    $reuse = Test-AgentValidation -Record $author -ExpectedConfiguration $author.Configuration
    if (-not $reuse.ReusableForRecordedCommand) { throw 'Final author inputs are not reusable.' }
    $arguments = @($author.Arguments | ForEach-Object { if ($_ -eq 'trx;LogFileName=on02-06-step15-net48.trx') { 'trx;LogFileName=on02-parent-prerequisites-net48.trx' } else { $_ } })
    $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $arguments -WorkingDirectory $author.WorkingDirectory -Configuration $author.Configuration -InputManifestPath $author.InputManifestPath -RunDirectory $run -Name 'on02-parent-prerequisites-net48' -Kind Tests -TrxPath (Join-Path $evidence 'on02-parent-prerequisites-net48.trx') -TimeoutSeconds 600
    $baseline = Get-Content -LiteralPath (Join-Path $evidence 'on02-baseline-net48.json') -Raw | ConvertFrom-Json -Depth 30
    $expected = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($case in $baseline.Results.Tests) { $null = $expected.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
    $actual = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($case in $validation.Record.Results.Tests) { $null = $actual.Add($case.Identity.Substring($case.Identity.IndexOf(':') + 1) + '|' + $case.Outcome) }
    $specificationCheck = Compare-AgentManifest -Baseline $protected
    $summary = [pscustomobject][ordered]@{ CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o'); Validation = $validation.Path; Counts = $validation.Record.Results.Counts; OrdinalCaseMembershipMatches = $expected.SetEquals($actual); Protected = $specificationCheck; Passed = ($validation.Record.Success -and $expected.Count -eq 43 -and $actual.Count -eq 43 -and $expected.SetEquals($actual) -and $specificationCheck.Matches) }
    Save-AgentEvidence -Value $summary -RunDirectory $run -Name 'on02-parent-prerequisites-summary.json'
    $summary | ConvertTo-Json -Depth 6
    if (-not $summary.Passed) { throw 'Independent prerequisite gate failed.' }
}

