    if ($currentTasks.tasks.Count -lt $oldTasks.tasks.Count) { throw 'Historical tasks removed.' }
    foreach ($key in $oldTasks.Keys) {
        if ($key -ne 'tasks' -and -not $ordinal.Equals(($oldTasks[$key] | ConvertTo-Json -Depth 100 -Compress), ($currentTasks[$key] | ConvertTo-Json -Depth 100 -Compress))) { throw 'Task root setting changed.' }
    }
    for ($index = 0; $index -lt $oldTasks.tasks.Count; $index++) {
        if (-not $ordinal.Equals(($oldTasks.tasks[$index] | ConvertTo-Json -Depth 100 -Compress), ($currentTasks.tasks[$index] | ConvertTo-Json -Depth 100 -Compress))) { throw 'Historical task changed.' }
    }
    $addedTasks = @($currentTasks.tasks | Select-Object -Skip $oldTasks.tasks.Count)
    if (@($addedTasks | Where-Object { -not $_.label.StartsWith('ON-03 ', [StringComparison]::Ordinal) }).Count -gt 0) { throw 'Unexpected appended task.' }
    $readmePath = Join-Path $root 'README.md'
    $readme = Get-Content -LiteralPath $readmePath -Raw
    $codeBlocks = [Text.RegularExpressions.Regex]::Matches($readme, '(?ms)^```csharp[^\r\n]*\r?\n(?<code>.*?)^```[ \t]*(?:\r?$)')
    $compilation = Get-Content -LiteralPath (Join-Path $evidence 'on03-readme-compilation-r3.json') -Raw | ConvertFrom-Json -Depth 30
    if (-not $compilation.Passed -or $codeBlocks.Count -ne 5) { throw 'Missing successful example compilation.' }
    $snippetChecks = @()
    for ($index = 0; $index -lt $codeBlocks.Count; $index++) {
        $sourceHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($codeBlocks[$index].Groups['code'].Value)))
        $records = @($compilation.Examples | Where-Object { $_.Example -eq ($index + 1) })
        $matches = $records.Count -eq 2
        foreach ($record in $records) {
            $matches = $matches -and $ordinal.Equals($sourceHash, $record.SourceSHA256) -and $record.EmittedInMemory -and -not $record.Executed -and $record.Diagnostics.Count -eq 0 -and $ordinal.Equals((Get-FileHash -LiteralPath $record.Library -Algorithm SHA256).Hash, $record.LibrarySHA256)
        }
        $snippetChecks += [pscustomobject]@{ Example = $index + 1; SourceSHA256 = $sourceHash; BothCompiledInputsMatch = $matches; Executed = $false }
        if (-not $matches) { throw 'README code or compiled library changed after successful compilation.' }
    }
    $previousHistory = @(& git -C $root show 'HEAD:CHANGELOG.md')
    if ($LASTEXITCODE -ne 0) { throw 'Cannot inspect released history.' }
    $historyLines = @(Get-Content -LiteralPath (Join-Path $root 'CHANGELOG.md'))
    $historyStart = [Array]::IndexOf([string[]]$historyLines, '# v3.0.1')
    if ($historyStart -lt 1) { throw 'Unreleased/history boundary missing.' }
    $previousText = ($previousHistory -join [char]10).TrimEnd([char]10)
    $currentHistoryText = ($historyLines[$historyStart..($historyLines.Count - 1)] -join [char]10).TrimEnd([char]10)
    if (-not $ordinal.Equals($previousText, $currentHistoryText)) { throw 'Released history content changed.' }
    $oldRequirementLines = @(& git -C $root show 'HEAD:docs/requirements.md')
    if ($LASTEXITCODE -ne 0) { throw 'Cannot inspect earlier requirements.' }
    $oldRequirements = $oldRequirementLines -join [char]10
    $requirements = (Get-Content -LiteralPath (Join-Path $root 'docs/requirements.md') -Raw).Replace([string][char]13, '')
    $membershipPattern = '(?ms)^### R-01\b.*?(?=^### R-06\b)'
    $oldMembership = [regex]::Match($oldRequirements, $membershipPattern).Value
    $newMembership = [regex]::Match($requirements, $membershipPattern).Value
    if ([string]::IsNullOrEmpty($oldMembership) -or -not $ordinal.Equals($oldMembership, $newMembership)) { throw 'R-01 through R-05 changed.' }
    $priorGreen = Get-Content -LiteralPath (Join-Path $evidence 'on03-parent-green-summary.json') -Raw | ConvertFrom-Json -Depth 30
    $buildChecks = @()
    foreach ($buildPath in @($priorGreen.Builds) + @($priorGreen.Results | ForEach-Object Build)) {
        $buildRecord = Get-Content -LiteralPath $buildPath -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $reuse = Test-AgentValidation -Record $buildRecord -ExpectedConfiguration $buildRecord.Configuration
        $buildChecks += [pscustomobject]@{ Path = $buildPath; Reuse = $reuse }
        if (-not $reuse.ReusableForRecordedCommand) { throw 'Successful build evidence no longer matches current inputs.' }
    }
    function Read-SafeXml([string]$path) {
        $settings = [Xml.XmlReaderSettings]::new()
        $settings.DtdProcessing = [Xml.DtdProcessing]::Prohibit
        $settings.XmlResolver = $null
        $reader = [Xml.XmlReader]::Create($path, $settings)
        try { $document = [Xml.XmlDocument]::new(); $document.XmlResolver = $null; $document.Load($reader); return ,$document } finally { $reader.Dispose() }
    }
    $finalResults = @()
    foreach ($leg in $priorGreen.Results) {
        $prior = Get-Content -LiteralPath $leg.Test -Raw | ConvertFrom-Json -AsHashtable -Depth 30
        $reuse = Test-AgentValidation -Record $prior -ExpectedConfiguration $prior.Configuration
        if (-not $reuse.ReusableForRecordedCommand) { throw 'Test outputs or inputs drifted before final execution.' }
        $name = 'on03-final-' + $leg.Framework.Replace('.', '')
        $arguments = @($prior.Arguments | ForEach-Object { if ($_.StartsWith('trx;LogFileName=', [StringComparison]::Ordinal)) { 'trx;LogFileName=' + $name + '.trx' } else { $_ } })
        $validation = Invoke-AgentValidation -FilePath dotnet -ArgumentList $arguments -WorkingDirectory $root -Configuration $prior.Configuration -InputManifestPath $prior.InputManifestPath -RunDirectory $run -Name $name -Kind Tests -TrxPath (Join-Path $evidence ($name + '.trx')) -TimeoutSeconds 600
        $comparison = Compare-AgentTestResults -Before $prior -After $validation.Record
        $beforeCases = [Collections.Generic.HashSet[string]]::new($ordinal)
        $afterCases = [Collections.Generic.HashSet[string]]::new($ordinal)
        foreach ($case in $prior.Results.Tests) { $null = $beforeCases.Add($case.Identity + '|' + $case.Outcome) }
        foreach ($case in $validation.Record.Results.Tests) { $null = $afterCases.Add($case.Identity + '|' + $case.Outcome) }
        $sameCases = $beforeCases.Count -eq $prior.Results.Counts.Total -and $afterCases.Count -eq $validation.Record.Results.Counts.Total -and $beforeCases.SetEquals($afterCases)
        if (-not $validation.Record.Success -or -not $comparison.Matches -or -not $sameCases) { throw 'Final focused execution did not preserve successful method/data identities.' }
        $trx = Read-SafeXml $validation.Record.TrxPath
        $deployment = @($trx.GetElementsByTagName('Deployment'))[0].GetAttribute('runDeploymentRoot')
        $collectors = @($trx.GetElementsByTagName('Collector') | Where-Object { $_.GetAttribute('uri') -ceq 'datacollector://microsoft/CoverletCodeCoverage/1.0' })
        if ($collectors.Count -ne 1) { throw 'Coverage collector link is missing or ambiguous.' }
        $coverageRecords = @()
        foreach ($attachment in $collectors[0].GetElementsByTagName('A')) {
            $coveragePath = [IO.Path]::GetFullPath((Join-Path (Join-Path (Join-Path $evidence $deployment) 'In') $attachment.GetAttribute('href')))
            if (-not $coveragePath.StartsWith([IO.Path]::GetFullPath($evidence) + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { throw 'Coverage link escapes evidence root.' }
            $coverage = Read-SafeXml $coveragePath
            $classResults = @()
            foreach ($className in @('ProphetsWay.Utilities.DestinationLabelPolicy', 'ProphetsWay.Utilities.SensitivityLabel')) {
                $classes = @($coverage.GetElementsByTagName('class') | Where-Object { $_.GetAttribute('name') -ceq $className })
                if ($classes.Count -ne 1) { throw 'Coverage did not identify the actual scoped class.' }
                $hits = @($classes[0].SelectNodes('./lines/line') | Where-Object { [int]$_.GetAttribute('hits') -gt 0 }).Count
                if ($hits -le 0) { throw 'No real source execution coverage.' }
                $classResults += [pscustomobject]@{ Class = $className; HitLines = $hits }
            }
            $coverageRecords += [pscustomobject]@{ Path = $coveragePath; SHA256 = (Get-FileHash -LiteralPath $coveragePath -Algorithm SHA256).Hash; Classes = $classResults }
        }
        if ($coverageRecords.Count -eq 0) { throw 'Missing coverage attachment.' }
        $libraryPath = Join-Path $root ('ProphetsWay.Logger/bin/Debug/' + $leg.LibraryAsset + '/ProphetsWay.Logger.dll')
        $copyPath = Join-Path $root ('ProphetsWay.Logger.Test/bin/Debug/' + $leg.Framework + '/ProphetsWay.Logger.dll')
        $bindingMatches = $ordinal.Equals((Get-FileHash -LiteralPath $libraryPath -Algorithm SHA256).Hash, $leg.MatchingSHA256) -and $ordinal.Equals((Get-FileHash -LiteralPath $copyPath -Algorithm SHA256).Hash, $leg.MatchingSHA256)
        if (-not $bindingMatches) { throw 'Library asset/copy changed.' }
        $finalResults += [pscustomobject]@{ Framework = $leg.Framework; Validation = $validation.Path; Counts = $validation.Record.Results.Counts; OrdinalCaseMatch = $sameCases; Coverage = $coverageRecords; LibraryAsset = $leg.LibraryAsset; PriorTargetAttribute = $leg.TargetAttribute; PriorMetadataAndCurrentHashesMatch = $bindingMatches; Passed = $true }
    }
    $finalCandidateCheck = Compare-AgentManifest -Baseline $candidate
    $finalExisting = Compare-AgentManifest -Baseline $existing
    $finalSpecifications = Compare-AgentManifest -Baseline $specifications
    $summary = [pscustomobject][ordered]@{
        CheckedUtc = [DateTimeOffset]::UtcNow.ToString('o')
        Head = $head
        Branch = $branch
        StagedPaths = $staged
        CandidateManifest = $candidatePath
        CandidateUnchanged = $finalCandidateCheck
        OriginalInputs = $finalExisting
        Specifications = $finalSpecifications
        TaskPreservation = [pscustomobject]@{ OriginalCount = $oldTasks.tasks.Count; CurrentCount = $currentTasks.tasks.Count; ExistingEntriesUnchanged = $true; AppendedLabels = @($addedTasks | ForEach-Object label) }
        ReadmeExamples = $snippetChecks
        ReleasedHistoryContentUnchangedIgnoringTerminalLineEndings = $true
        MembershipRequirementsR01ThroughR05Unchanged = $true
        BuildsReusable = $buildChecks
        FreshTests = $finalResults
        Limitations = @('Windows focused selection only; no full suite or file/default-output tests', 'README examples compiled in memory but never executed', 'README trailing-blank Markdown diagnostics and legacy changelog diagnostics remain disclosed', 'No staging, commit, push, package, release, example execution or live operation')
        Passed = ($finalCandidateCheck.Matches -and $finalExisting.Matches -and $finalSpecifications.Matches -and $finalResults.Count -eq 2)
    }
    Save-AgentEvidence -Value $summary -RunDirectory $run -Name 'on03-final-verification-r1.json'
    $summary | ConvertTo-Json -Depth 8
    if (-not $summary.Passed) { throw 'Final evidence preservation failed.' }
}
